// src/components/Dashboard.js
import React from 'react';
import { useNavigate } from 'react-router-dom';
import '../App.css';

const Dashboard = ({ user }) => {
  const navigate = useNavigate();

  return (
    <div className="container" style={{ padding: '2rem' }}>
      {/* Greeting Section */}
      <div className="text-center mb-5">
        <h1 className="title">Hello, {user?.name}!</h1>
        <p className="subtitle">Choose the type of area you want to monitor</p>
      </div>

      {/* Divided Section */}
      <div
        className="row"
        style={{
          display: 'flex',
          justifyContent: 'center',
          gap: '2rem',
          flexWrap: 'wrap',
        }}
      >
        {/* Prohibited Area Card */}
        <div
          style={{
            flex: '1',
            minWidth: '300px',
            maxWidth: '500px',
            backgroundColor: '#fffaf2',
            padding: '1.5rem',
            borderRadius: '12px',
            boxShadow: '0 6px 12px rgba(255, 140, 0, 0.1)',
          }}
        >
          <h3 style={{ color: '#ff8c00' }}>Prohibited Area</h3>
          <ul style={{ paddingLeft: '1.2rem', marginTop: '1rem' }}>
            
          </ul>
          <button
            className="submit-button mt-3 w-100"
            onClick={() => navigate('/prohibited-area')}
          >
            Prohibited Area
          </button>
        </div>

        {/* Strictly Prohibited Area Card */}
        <div
          style={{
            flex: '1',
            minWidth: '300px',
            maxWidth: '500px',
            backgroundColor: '#fffaf2',
            padding: '1.5rem',
            borderRadius: '12px',
            boxShadow: '0 6px 12px rgba(255, 140, 0, 0.1)',
          }}
        >
          <h3 style={{ color: '#d32f2f' }}>Strictly Prohibited Area</h3>
          <ul style={{ paddingLeft: '1.2rem', marginTop: '1rem' }}>
            <li>24/7 surveillance</li>
            <li>Immediate alerts & lockdown</li>
            <li>High-priority zones</li>
          </ul>
          <button
            className="submit-button mt-3 w-100"
            onClick={() => navigate('/strictly-prohibited-area')}
          >
            Strictly Prohibited Area
          </button>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
